    {
        [Key]
        public int Id { get; set; }

        ...

        public virtual ICollection<Question> Questions { get; set; }
    }
}
```

**Models/Question.cs**

```csharp
namespace QuizManagerWeb.Models
{
    public class Question
    {
        [Key]
        public int Id { get; set; }

        ...

        [ForeignKey("Quiz")]
        public int QuizId { get; set; }

        public virtual Quiz Quiz { get; set; }
    }
}
```

